from paging import paginate_pairs

def test_pairs_tail():
    assert paginate_pairs([1, 2, 3], 2) == [(1, [1, 2]), (3, [3])]

def test_pairs_empty():
    assert paginate_pairs([], 2) == []

def test_pairs_single_pass():
    assert paginate_pairs([1], 5) == [(1, [1])]


from parsing import split_path

def test_path_quoted_slash():
    assert split_path('a/"b/c"/d') == ["a", "b/c", "d"]

def test_path_leading_slash():
    assert split_path("/a/b") == ["a", "b"]

def test_path_empty():
    assert split_path("") == []
